interface PaymentListFilters { revision: number; direction?: PaymentHistoryDirection; }
interface PaymentPopupMenuContext {
  action: 'open-cards' | 'add-card' | 'confirm-card' | 'set-history-direction';
  direction?: PaymentHistoryDirection;
}

@Component({
  selector: 'app-payment-methods-popup',
  standalone: true,
  imports: [PopupComponent, SmartListComponent, PaymentCardComponent, SingleRowComponent, I18nPipe],
  templateUrl: './payment-methods-popup.component.html',
  styleUrl: './payment-methods-popup.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PaymentMethodsPopupComponent implements OnDestroy {
  protected readonly store = inject(PaymentMethodsPopupStore);
  private readonly userProfileStore = inject(UserProfileStore);
  private readonly users = inject(UsersService);
  private readonly activityStore = inject(ActivityStore);
  private readonly paymentMethods = inject(PaymentMethodsService);
  private readonly deploymentConfiguration = inject(DeploymentConfigurationService);
  private readonly events = inject(EventsService);
  private readonly activities = inject(ActivitiesPopupStore);
  private readonly eventCheckoutDialog = inject(EventCheckoutDialogStore);
  private readonly assets = inject(AssetsService);
  private readonly assetStore = inject(AssetStore);
  private readonly assetPopup = inject(AssetPopupStore);
  private readonly dialogStore = inject(DialogStore);
  private readonly sanitizer = inject(DomSanitizer);
  private readonly i18n = inject(I18nService);

  private readonly revisionRef = signal(0);
  private readonly canAddRef = signal(false);
  private readonly cardsOpenRef = signal(false);
  private readonly registrationRef = signal<{
    id: string;
    url: string;
    safeUrl: SafeResourceUrl;
    provider: PaymentProvider;
    expiresAtIso: string;
    replacesPaymentMethodId: string | null;
  } | null>(null);
  private readonly registrationFrameOpenRef = signal(false);
  private readonly busyRef = signal(false);
  private readonly errorRef = signal('');
  private readonly spendingTotalsRef = signal<Record<string, number>>({});
  private readonly incomeTotalsRef = signal<Record<string, number>>({});
  private readonly historyDirectionRef = signal<PaymentHistoryDirection>('all');
  private readonly pendingRefundCountRef = signal(0);
  private readonly historyTotalsLoadedRef = signal(false);
  private readonly loadedCardsById = new Map<string, SavedPaymentMethodDto>();
  private registrationPoll: ReturnType<typeof setTimeout> | null = null;
  private registrationRefreshInFlight = false;

  protected readonly cardsOpen = this.cardsOpenRef.asReadonly();
  protected readonly registration = this.registrationRef.asReadonly();
  protected readonly registrationFrameOpen = this.registrationFrameOpenRef.asReadonly();
  protected readonly busy = this.busyRef.asReadonly();
  protected readonly error = this.errorRef.asReadonly();
  protected readonly spendingTotals = this.spendingTotalsRef.asReadonly();
  protected readonly historyDirection = this.historyDirectionRef.asReadonly();
  protected readonly localMode = this.paymentMethods.localModeEnabled;
  protected readonly pickerMode = computed(() => this.store.picker() !== null);

  protected readonly query = computed<Partial<ListQuery<PaymentListFilters>>>(() => ({
    page: 0,
    pageSize: 6,
    sort: 'createdAt',
    direction: 'desc',
    filters: { revision: this.revisionRef() }
  }));

  protected readonly allHistoryQuery = computed<Partial<ListQuery<PaymentListFilters>>>(() => ({
    page: 0,
    pageSize: 20,
    sort: 'createdDate',
    direction: 'desc',
    filters: { revision: this.revisionRef(), direction: this.historyDirectionRef() }
  }));

  protected readonly cardListConfig: SmartListConfig<SavedPaymentMethodDto, PaymentListFilters> = {
    pageSize: 6,
    defaultView: 'list',
    showStickyHeader: false,
    emptyLabel: 'payment.cards.empty',
    emptyDescription: this.localMode
      ? 'payment.cards.empty.local.description'
      : 'payment.cards.empty.description',
    listLayout: 'card-grid',
    desktopColumns: 2,
    mobileColumns: 1,
    snapMode: 'none',
    headerProgress: { enabled: true, placement: 'inline', tone: 'accent' },
    containerClass: { 'payment-method-card-list': true },
    trackBy: (_index, item) => item.id
  };

  protected readonly allHistoryListConfig: SmartListConfig<PaymentHistoryItemDto, PaymentListFilters> = {
    pageSize: 20,
    defaultView: 'list',
    showStickyHeader: false,
    emptyLabel: 'payment.history.empty',
    emptyDescription: 'payment.history.empty.description',
    listLayout: 'stack',
    snapMode: 'none',
    groupBy: item => `${item.createdAtIso ?? ''}`.slice(0, 10),
    showFirstGroupMarker: true,
    headerProgress: { enabled: true, placement: 'inline', tone: 'accent' },
    trackBy: (_index, item) => item.id
  };

  protected readonly loadCards: SmartListLoadPage<SavedPaymentMethodDto, PaymentListFilters> = (query, context) => from(
    this.paymentMethods.queryPage(this.activeUserId(), query, context?.signal).then(page => {
      if (page.currentProvider) {
        this.deploymentConfiguration.applyPaymentProviderId(
          page.currentProvider === 'none' ? null : page.currentProvider
        );
      }
      const orderedItems = this.orderPaymentMethods(page.items);
      this.loadedCardsById.clear();
      orderedItems.forEach(item => this.loadedCardsById.set(item.id, { ...item }));
      this.canAddRef.set(page.canAdd === true);
      if (page.pendingRegistration?.status === 'pending') {
        this.trackRegistration(page.pendingRegistration, false);
      }
      const pending = page.pendingRegistration?.status === 'pending'
        ? this.pendingPaymentMethod(page.pendingRegistration)
        : null;
      if (!pending) return { ...page, items: orderedItems };
      const replacedId = page.pendingRegistration?.replacesPaymentMethodId?.trim() || null;
      const replaced = Boolean(replacedId && orderedItems.some(item => item.id === replacedId));
      const items = replaced
        ? orderedItems.map(item => item.id === replacedId ? pending : item)
        : [...orderedItems, pending];
      return { ...page, items, total: Math.min(6, page.total + (replaced ? 0 : 1)) };
    })
  );

  protected readonly loadAllHistory: SmartListLoadPage<PaymentHistoryItemDto, PaymentListFilters> = (query, context) => from(
    this.paymentMethods.queryAllHistory(this.activeUserId(), query, context?.signal).then(page => {
      this.spendingTotalsRef.set({ ...page.spendingTotals });
      this.incomeTotalsRef.set({ ...page.incomeTotals });
      this.historyTotalsLoadedRef.set(true);
      this.pendingRefundCountRef.set(Math.max(0, Math.trunc(Number(page.pendingRefundCount) || 0)));
      return page;
    })
  );

  protected mainPopupModel(): PopupModel<PaymentPopupMenuContext> {
    return {
      title: 'payment.history.title',
      subtitle: 'payment.history.subtitle',
      ariaLabel: 'payment.history.title',
      closeAriaLabel: 'payment.history.close',
      size: 'wide',
      height: 'full',
      bodyLayout: 'fill',
      headerTone: 'accent',
      headerPalette: 'blue',
      headerControls: [this.historyFilterControl(), this.headerActionControl({
        id: 'open-cards',
        icon: 'credit_card',
        label: 'payment.cards.open',
        ariaLabel: 'payment.cards.open.aria',
        palette: 'blue',
        layout: 'pill',
        action: 'custom',
        context: { action: 'open-cards' }
      })],
      onMenuSelect: event => this.onHeaderMenuSelect(event),
      onClose: () => this.closeAll()
    };
  }

  protected cardsPopupModel(): PopupModel<PaymentPopupMenuContext> {
    const headerControls: PopupControl<PaymentPopupMenuContext>[] = [this.headerActionControl({
      id: 'add-card',
      icon: 'add',
      label: 'payment.cards.add',
      ariaLabel: 'payment.cards.add.aria',
      disabled: this.localMode || !this.canAddRef() || this.busyRef() || this.registrationRef() !== null,
      palette: 'green',
      layout: 'pill',
      action: 'custom',
      context: { action: 'add-card' }
    })];
    if (this.pickerMode()) {
      headerControls.push(this.headerActionControl({
        id: 'confirm-card',
        icon: 'done',
        ariaLabel: 'payment.cards.select.confirm',
        disabled: !this.selectedPaymentMethod(),
        palette: 'green',
        layout: 'icon',
        action: 'custom',
        context: { action: 'confirm-card' }
      }));
    }
    return {
      title: this.pickerMode() ? 'payment.cards.select.title' : 'payment.cards.title',
      subtitle: this.localMode ? 'payment.cards.subtitle.local' : 'payment.cards.subtitle',
      ariaLabel: this.pickerMode() ? 'payment.cards.select.aria' : 'payment.cards.manage.aria',
      closeAriaLabel: 'payment.cards.close',
      size: 'wide',
      height: 'full',
      bodyLayout: 'fill',
      headerTone: 'accent',
      headerPalette: 'blue',
      headerControls,
      onMenuSelect: event => this.onHeaderMenuSelect(event),
      onClose: () => this.closeCards()
    };
  }

  protected registrationPopupModel(): PopupModel {
    return {
      title: 'payment.registration.title',
      subtitle: 'payment.registration.subtitle',
      ariaLabel: 'payment.registration.aria',
      closeAriaLabel: 'payment.registration.close',
      size: 'default',
      height: 'full',
      bodyLayout: 'flush',
      headerTone: 'accent',
      headerPalette: 'green',
      onClose: () => this.closeRegistration()
    };
  }

  protected registrationProviderLogo(provider: PaymentProvider): string {
    return `assets/payment-providers/${provider}.svg`;
  }

  protected registrationProviderLabel(provider: PaymentProvider): string {
    return provider === 'barion' ? 'Barion' : 'Stripe';
  }

  protected paymentCard(method: SavedPaymentMethodDto): PaymentCardData {
    const loading = method.status === 'registering';
    const expired = this.paymentMethodExpired(method);
    const requiresRetokenization = !this.localMode && !loading && !expired
      && this.paymentMethodRequiresRetokenization(method);
    const deleteAction = {
      id: 'delete-payment-card',
      label: 'payment.cards.delete',
      icon: 'delete',
      tone: 'destructive' as const
    };
    return {
      id: method.id,
      provider: method.provider,
      brand: method.brand,
      last4: method.last4,
      expiryMonth: method.expiryMonth,
      expiryYear: method.expiryYear,
      cardholderName: method.cardholderName,
      artworkUrl: method.artworkUrl,
      loading,
      loadingLabel: loading ? 'payment.registration.pending' : undefined,
      disabled: loading || expired || requiresRetokenization,
      expired,
      requiresRetokenization,
      selected: !expired && !requiresRetokenization && this.pickerMode()
        && this.store.selectedPaymentMethodId() === method.id,
      paymentMenuActions: loading
        ? []
        : expired
          ? [deleteAction]
          : requiresRetokenization
            ? [
                {
                  id: 'retokenize-payment-card',
                  label: 'payment.cards.retokenize',
                  icon: 'published_with_changes',
                  tone: 'warning' as const
                },
                deleteAction
              ]
            : this.pickerMode()
              ? []
              : [
                  {
                    id: 'replace-payment-card',
                    label: 'payment.cards.replace',
                    icon: 'published_with_changes',
                    tone: 'accent' as const
                  },
                  deleteAction
                ]
    };
  }

  protected historyRow(item: PaymentHistoryItemDto, withMenu = false): SingleRowData<PaymentHistoryItemDto> {
    const refundAudit = item.auditKind === 'refund';
    const amount = this.formatSignedCurrency(
      Number(item.amount) || 0,
      item.currency || 'HUF',
      item.direction === 'income' ? '+' : '−'
    );
    const date = new Date(item.createdAtIso);
    const statusLabel = this.paymentStatusLabel(item.status);
    return {
      id: item.id,
      title: amount,
      surfaceTone: item.direction === 'income' ? 'success' : 'danger',
      subtitle: item.sourceId || this.i18n.translate('payment'),
      detail: Number.isNaN(date.getTime()) ? null : date.toLocaleString(undefined, {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      }),
      icon: item.status === 'captured' ? 'check_circle' : refundAudit ? 'currency_exchange' : 'payments',
      avatarToneClass: `payment-history-avatar payment-history-avatar--${
        item.status === 'failed' ? 'failed' : item.direction
      }`,
      badges: [
        {
          label: item.provider,
          icon: item.provider.toLowerCase() === 'stripe' ? 'payment' : 'account_balance_wallet',
          tone: item.provider.toLowerCase() === 'stripe' ? 'info' : 'accent',
          position: 'inline'
        },
        {
          label: statusLabel,
          tone: item.direction === 'income' ? 'success' : 'danger',
          className: item.direction === 'income'
            ? 'payment-history-status-badge--success'
            : 'payment-history-status-badge--danger',
          position: 'top-right'
        },
        ...(!refundAudit && item.refundRequestStatus === 'pending'
          ? [{
              label: this.i18n.translate('payment.history.refund.pending'),
              icon: 'pending_actions',
              tone: 'warning' as const,
              position: 'inline' as const
            }]
          : [])
      ],
      menuActions: withMenu ? this.paymentHistoryMenuActions(item) : [],
      eagerDetail: item
    };
  }

  protected onPaymentHistoryMenuSelect(event: AppMenuItemSelectEvent<string, unknown>): void {
    const row = (event.context as { row?: SingleRowData<PaymentHistoryItemDto> } | undefined)?.row;
    const item = row?.eagerDetail;
    if (!item) return;
    if (event.id === 'paymentSummary') {
      void this.openPaymentSummary(item);
    } else if (event.id === 'requestRefund') {
      this.confirmRefundRequest(item);
    } else if (event.id === 'approveRefund') {
      this.confirmRefundApproval(item);
    } else if (event.id === 'askAssetOwner' || event.id === 'askOrganizer') {
      void this.openPaymentServiceChat(item);
    }
  }

  protected selectCard(method: SavedPaymentMethodDto, event: Event): void {
    event.preventDefault();
    event.stopPropagation();
    if (!this.pickerMode() || method.status !== 'active' || this.paymentMethodExpired(method)
      || this.paymentMethodRequiresRetokenization(method)) return;
    this.store.togglePickerSelection(method.id);
  }

  protected onCardMenuSelect(event: AppMenuItemSelectEvent<string, unknown>): void {
    const context = event.context as {
      menu?: string;
      item?: SavedPaymentMethodDto;
      paymentMethodId?: string;
    } | undefined;
    const paymentMethodId = `${context?.paymentMethodId ?? context?.item?.id ?? ''}`.trim();
    const method = context?.item ?? this.loadedCardsById.get(paymentMethodId) ?? null;
    if (!method) return;
    event.sourceEvent.preventDefault();
    event.sourceEvent.stopPropagation();
    if (event.id === 'replace-payment-card' || event.id === 'retokenize-payment-card') {
      void this.beginRegistration(method.id);
    } else if (event.id === 'delete-payment-card') {
      this.confirmDelete(method);
    }
  }

  private confirmDelete(method: SavedPaymentMethodDto): void {
    this.dialogStore.open({
      title: 'payment.cards.delete.title',
      message: this.i18n.translateParams('payment.cards.delete.message', {
        brand: method.brand,
        last4: method.last4
      }),
      cancelLabel: 'cancel',
      confirmLabel: 'payment.cards.delete',
      busyConfirmLabel: 'payment.cards.delete.busy',
      confirmTone: 'danger',
      failureMessage: 'payment.cards.delete.error',
      onConfirm: async () => {
        await this.paymentMethods.deletePaymentMethod(this.activeUserId(), method.id);
        this.loadedCardsById.delete(method.id);
        this.errorRef.set('');
        this.revisionRef.update(value => value + 1);
      }
    });
  }

  @HostListener('window:message', ['$event'])
  protected onProviderMessage(event: MessageEvent): void {
    const registration = this.registrationRef();
    if (!registration || event.origin !== this.origin(registration.url)) return;
    const payload = event.data as { type?: string; registrationId?: string; status?: string } | null;
    if (payload?.type !== 'myscoutee:payment-method-registration' || payload.registrationId !== registration.id) return;
    if (payload.status === 'completed' || payload.status === 'cancelled' || payload.status === 'expired' || payload.status === 'failed') {
      this.registrationFrameOpenRef.set(false);
      void this.refreshRegistration();
    }
  }

  private onHeaderMenuSelect(event: PopupMenuSelectEvent<PaymentPopupMenuContext>): void {
    event.itemSelect.sourceEvent.preventDefault();
    event.itemSelect.sourceEvent.stopPropagation();
    const action = event.itemSelect.context?.action;
    if (action === 'set-history-direction') {
      const direction = event.itemSelect.context?.direction;
      if (direction && direction !== this.historyDirectionRef()) {
        this.historyDirectionRef.set(direction);
        this.revisionRef.update(value => value + 1);
      }
      return;
    }
    if (action === 'add-card') {
      void this.beginRegistration(null);
      return;
    }
    if (action === 'open-cards') {
      this.errorRef.set('');
      this.cardsOpenRef.set(true);
      return;
    }
    if (action === 'confirm-card') {
      const selected = this.selectedPaymentMethod();
      if (selected) this.store.confirm(selected);
    }
  }

  private selectedPaymentMethod(): SavedPaymentMethodDto | null {
    const selectedId = this.store.selectedPaymentMethodId();
    const selected = selectedId ? this.loadedCardsById.get(selectedId) ?? null : null;
    return selected?.status === 'active' && !this.paymentMethodExpired(selected)
      && !this.paymentMethodRequiresRetokenization(selected)
      ? selected
      : null;
  }

  private paymentMethodRequiresRetokenization(method: SavedPaymentMethodDto): boolean {
    const activeProvider = `${this.deploymentConfiguration.paymentProviderId() ?? ''}`.trim().toLowerCase();
    const tokenProvider = `${method.provider ?? ''}`.trim().toLowerCase();
    return Boolean(activeProvider && tokenProvider && activeProvider !== tokenProvider);
  }

  private orderPaymentMethods(methods: readonly SavedPaymentMethodDto[]): SavedPaymentMethodDto[] {
    return methods
      .map((method, index) => ({ method, index }))
      .sort((left, right) => this.paymentMethodDisplayRank(left.method)
        - this.paymentMethodDisplayRank(right.method)
        || left.index - right.index)
      .map(({ method }) => method);
  }

  private paymentMethodDisplayRank(method: SavedPaymentMethodDto): number {
    if (this.paymentMethodExpired(method)) return 2;
    return this.paymentMethodRequiresRetokenization(method) ? 1 : 0;
  }

  private paymentMethodExpired(method: SavedPaymentMethodDto): boolean {
    if (`${method.status ?? ''}`.trim().toLowerCase() === 'expired') return true;
    const year = Number(method.expiryYear);
    const month = Number(method.expiryMonth);
    if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) return true;
    return Date.now() >= Date.UTC(year, month, 1);
  }

  private async beginRegistration(replacesPaymentMethodId: string | null): Promise<void> {
    if (this.localMode || this.busyRef()) return;
    this.busyRef.set(true);
    this.errorRef.set('');
    try {
      const registration = await this.paymentMethods.beginRegistration(this.activeUserId(), {
        replacesPaymentMethodId
      });
      this.trackRegistration(registration, true);
      this.revisionRef.update(value => value + 1);
    } catch (error) {
      if (error instanceof Error && 'error' in error) {
        this.deploymentConfiguration.applyPaymentProviderChangeResponse(
          (error as Error & { error?: unknown }).error
        );
      }
      this.errorRef.set(this.errorKey(error, 'payment.registration.error.start'));
    } finally {
      this.busyRef.set(false);
    }
  }

  private startRegistrationPolling(): void {
    this.stopRegistrationPolling();
    this.registrationPoll = setTimeout(() => void this.refreshRegistration(), 1500);
  }

  private async refreshRegistration(): Promise<void> {
    const current = this.registrationRef();
    if (!current || this.registrationRefreshInFlight) return;
    this.registrationRefreshInFlight = true;
    try {
      const registration = await this.paymentMethods.refreshRegistration(this.activeUserId(), current.id);
      if (registration.status === 'pending') {
        if (this.registrationExpired(current.expiresAtIso)) this.finishRegistration('expired');
        return;
      }
      if (registration.status === 'completed' && registration.paymentMethod) {
        this.loadedCardsById.set(registration.paymentMethod.id, { ...registration.paymentMethod });
        if (this.pickerMode()) {
          this.store.selectPickerPaymentMethod(registration.paymentMethod.id);
        }
      }
      this.finishRegistration(registration.status);
      if (registration.status === 'completed') {
        this.errorRef.set('');
      } else if (registration.status === 'cancelled') {
        this.errorRef.set('payment.registration.error.cancelled');
      } else if (registration.status === 'expired') {
        this.errorRef.set('payment.registration.error.expired');
      } else {
        this.errorRef.set('payment.registration.error.failed');
      }
    } catch (error) {
      if (error instanceof Error && 'error' in error) {
        this.deploymentConfiguration.applyPaymentProviderChangeResponse(
          (error as Error & { error?: unknown }).error
        );
      }
      this.errorRef.set(this.errorKey(error, 'payment.registration.error.status'));
      if (this.registrationExpired(current.expiresAtIso)) this.finishRegistration('expired');
    } finally {
      this.registrationRefreshInFlight = false;
      if (this.registrationRef()?.id === current.id) this.startRegistrationPolling();
    }
  }

  private closeRegistration(): void {
    this.registrationFrameOpenRef.set(false);
  }

  private closeAll(): void {
    this.closeRegistration();
    this.cardsOpenRef.set(false);
    this.errorRef.set('');
    this.historyTotalsLoadedRef.set(false);
    this.spendingTotalsRef.set({});
    this.incomeTotalsRef.set({});
    this.store.close();
  }

  private closeCards(): void {
    this.closeRegistration();
    if (this.pickerMode()) {
      this.closeAll();
    } else {
      this.cardsOpenRef.set(false);
    }
  }

  private stopRegistrationPolling(): void {
    if (this.registrationPoll !== null) {
      clearTimeout(this.registrationPoll);
      this.registrationPoll = null;
    }
  }

  private trackRegistration(registration: PaymentMethodRegistrationDto, openFrame: boolean): void {
    if (registration.status !== 'pending') {
      this.finishRegistration(registration.status);
      return;
    }
    const paymentUrl = registration.paymentUrl?.trim() || '';
    if (!paymentUrl) throw new Error('payment.registration.error.page');
    const current = this.registrationRef();
    if (current?.id !== registration.id) {
      this.registrationRef.set({
        id: registration.id,
        url: paymentUrl,
        safeUrl: this.sanitizer.bypassSecurityTrustResourceUrl(paymentUrl),
        provider: registration.provider,
        expiresAtIso: registration.expiresAtIso,
        replacesPaymentMethodId: registration.replacesPaymentMethodId?.trim() || null
      });
      this.startRegistrationPolling();
    }
    if (openFrame) this.registrationFrameOpenRef.set(true);
  }

  private finishRegistration(status: string): void {
    this.stopRegistrationPolling();
    this.registrationFrameOpenRef.set(false);
    this.registrationRef.set(null);
    this.revisionRef.update(value => value + 1);
    if (status === 'expired') {
      this.errorRef.set('payment.registration.error.expired');
    }
  }

  private registrationExpired(expiresAtIso: string): boolean {
    const expiry = Date.parse(expiresAtIso);
    return Number.isFinite(expiry) && Date.now() >= expiry;
  }

  private pendingPaymentMethod(registration: PaymentMethodRegistrationDto): SavedPaymentMethodDto {
    return {
      id: `registration:${registration.id}`,
      provider: registration.provider,
      brand: '',
      last4: '',
      expiryMonth: 1,
      expiryYear: 2000,
      cardholderName: '',
      artworkKey: '',
      artworkUrl: '',
      status: 'registering',
      createdAtIso: '',
      updatedAtIso: ''
    };
  }

  private activeUserId(): string {
    const userId = this.userProfileStore.activeUserId().trim();
    if (!userId) throw new Error('payment.error.user.required');
    return userId;
  }

  private errorKey(error: unknown, fallback: string): string {
    const message = error instanceof Error ? error.message.trim() : '';
    return message.startsWith('payment.') ? message : fallback;
  }

  private origin(url: string): string {
    try { return new URL(url, window.location.href).origin; } catch { return ''; }
  }

  private headerActionControl(trigger: AppMenuTrigger): PopupControl<PaymentPopupMenuContext> {
    return { kind: 'menu', id: trigger.id ?? 'payment-header-action', trigger };
  }

  private paymentStatusLabel(status: string): string {
    const normalized = `${status ?? ''}`.trim().toLowerCase();
    return normalized ? this.i18n.translate(`payment.status.${normalized}`, status) : '';
  }

  private paymentStatusTone(status: string): 'neutral' | 'success' | 'danger' | 'refund' {
    switch (`${status ?? ''}`.trim().toLowerCase()) {
      case 'failed':
      case 'declined':
      case 'expired':
        return 'danger';
      case 'captured':
      case 'approved':
      case 'succeeded':
      case 'authorized':
        return 'success';
      case 'released':
      case 'refunded':
        return 'refund';
      default:
        return 'neutral';
    }
  }

  private isRefundedPaymentStatus(status: string): boolean {
    const normalized = `${status ?? ''}`.trim().toLowerCase();
    return normalized === 'released' || normalized === 'refunded' || normalized === 'partially_refunded';
  }

  protected historyHeaderTotals(): ReadonlyArray<{ text: string; tone: 'expense' | 'income' }> {
    const stored = this.userProfileStore.activeUserProfile()?.paymentTotals;
    const loadedOutgoing = this.spendingTotalsRef();
    const loadedIncoming = this.incomeTotalsRef();
    const outgoing = this.historyTotalsLoadedRef() ? loadedOutgoing : stored?.outgoing ?? {};
    const incoming = this.historyTotalsLoadedRef() ? loadedIncoming : stored?.incoming ?? {};
    const currencies = [...new Set([...Object.keys(outgoing), ...Object.keys(incoming)])]
      .map(currency => currency.trim().toUpperCase())
      .filter(Boolean)
      .sort((left, right) => left.localeCompare(right));
    return (currencies.length > 0 ? currencies : ['HUF']).flatMap(currency => [
      {
        text: this.formatSignedCurrency(Number(outgoing[currency]) || 0, currency, '−'),
        tone: 'expense' as const
      },
      {
        text: this.formatSignedCurrency(Number(incoming[currency]) || 0, currency, '+'),
        tone: 'income' as const
      }
    ]);
  }

  private historyFilterControl(): PopupControl<PaymentPopupMenuContext> {
    const direction = this.historyDirectionRef();
    const labels: Record<PaymentHistoryDirection, string> = {
      all: 'payment.history.filter.all',
      expenses: 'payment.history.filter.expenses',
      income: 'payment.history.filter.income'
    };
    const pendingRefundCount = this.pendingRefundCountRef();
    const items: AppMenuItem<string, PaymentPopupMenuContext>[] = (['all', 'expenses', 'income'] as const)
      .map(value => ({
        id: `payment-history-${value}`,
        label: labels[value],
        icon: value === 'all' ? 'swap_vert' : value === 'income' ? 'south_west' : 'north_east',
        kind: 'radio',
        palette: value === 'income' ? 'green' : value === 'expenses' ? 'red' : 'blue',
        active: value === direction,
        checked: value === direction,
        counter: value === 'all' || value === 'expenses' ? pendingRefundCount || undefined : undefined,
        context: { action: 'set-history-direction', direction: value }
      }));
    return {
      kind: 'menu',
      id: 'payment-history-filter',
      menuKind: 'select',
      title: 'payment.history.filter.title',
      trigger: {
        id: 'payment-history-filter-trigger',
        label: labels[direction],
        icon: 'filter_list',
        trailingIcon: 'expand_more',
        counter: pendingRefundCount || undefined,
        palette: direction === 'income' ? 'green' : direction === 'expenses' ? 'red' : 'blue',
        layout: 'pill',
        ariaLabel: 'payment.history.filter.title'
      },
      items,
      panelAlign: 'end',
      closeOnSelect: true
    };
  }

  private paymentHistoryMenuActions(item: PaymentHistoryItemDto): string[] {
    if (item.auditKind === 'refund') {
      return item.canApproveRefund === true ? ['approveRefund'] : [];
    }
    const actions = ['paymentSummary'];
    if (item.direction === 'expense' && `${item.recipientUserId ?? ''}`.trim()) {
      actions.push(item.serviceContext === 'asset' ? 'askAssetOwner' : 'askOrganizer');
    }
    if (item.canRequestRefund === true) actions.push('requestRefund');
    if (item.canApproveRefund === true) actions.push('approveRefund');
    return actions;
  }

  private confirmRefundRequest(item: PaymentHistoryItemDto): void {
    this.dialogStore.open({
      title: 'payment.history.refund.request.title',
      message: this.refundConfirmationMessage(item, 'payment.history.refund.request.message'),
      cancelLabel: 'cancel',
      confirmLabel: 'payment.history.refund.request',
      confirmTone: 'warning',
      failureMessage: 'payment.history.refund.request.error',
      onConfirm: async () => this.applyPaymentHistoryMutation(
        await this.paymentMethods.requestRefund(this.activeUserId(), item.id)
      )
    });
  }

  private confirmRefundApproval(item: PaymentHistoryItemDto): void {
    this.dialogStore.open({
      title: 'payment.history.refund.approve.title',
      message: this.refundConfirmationMessage(item, 'payment.history.refund.approve.message'),
      cancelLabel: 'cancel',
      confirmLabel: 'payment.history.refund.approve',
      confirmTone: 'accent',
      failureMessage: 'payment.history.refund.approve.error',
      onConfirm: async () => this.applyPaymentHistoryMutation(
        await this.paymentMethods.approveRefund(this.activeUserId(), item.id)
      )
    });
  }

  private refundConfirmationMessage(item: PaymentHistoryItemDto, leadKey: string): string {
    const preview = item.refundPreview;
    if (!preview) return this.i18n.translate(leadKey);
    const currency = preview.currency || item.currency || 'HUF';
    return [
      this.i18n.translate(leadKey),
      this.i18n.translateParams('payment.history.refund.preview.amount', {
        amount: this.formatSignedCurrency(preview.refundableAmount, currency, '+')
      }),
      this.i18n.translateParams('payment.history.refund.preview.retained', {
        amount: this.formatSignedCurrency(preview.retainedAmount, currency, '−')
      }),
      this.refundPolicyBasis(item)
    ].filter(Boolean).join('\n');
  }

  private refundPolicyBasis(item: PaymentHistoryItemDto): string {
    const preview = item.refundPreview;
    if (preview?.ruleId === 'assignment-manager-takeover') {
      return this.i18n.translate('payment.history.refund.preview.takeover');
    }
    if (!preview?.ruleId) {
      return preview?.ruleDescription || this.i18n.translate('payment.history.refund.preview.no.policy');
    }
    const currency = preview.currency || item.currency || 'HUF';
    const refund = preview.refundKind === 'full'
      ? this.i18n.translate('payment.history.refund.preview.full')
      : preview.refundKind === 'fixed_amount'
        ? this.formatSignedCurrency(Number(preview.refundValue) || 0, currency, '+')
        : preview.refundKind === 'none'
          ? this.i18n.translate('payment.history.refund.preview.none')
          : this.i18n.translateParams('payment.history.refund.preview.percent', {
              percent: Number(preview.refundValue) || 0
            });
    return this.i18n.translateParams('payment.history.refund.preview.policy', {
      refund,
      offset: Math.max(0, Number(preview.ruleOffsetValue) || 0),
      unit: this.i18n.translate(`payment.history.refund.preview.unit.${preview.ruleOffsetUnit || 'days'}`)
    });
  }

  private applyPaymentHistoryMutation(mutation: AppDTOs.PaymentHistoryMutationDto): void {
    const userId = this.activeUserId();
    const pendingRefundCount = Math.max(0, Math.trunc(Number(mutation.pendingRefundCount) || 0));
    this.spendingTotalsRef.set({ ...mutation.spendingTotals });
    this.incomeTotalsRef.set({ ...mutation.incomeTotals });
    this.historyTotalsLoadedRef.set(true);
    this.pendingRefundCountRef.set(pendingRefundCount);
    this.activityStore.patchUserCounterOverrides(userId, { paymentRefundsPending: pendingRefundCount });
    this.userProfileStore.patchActiveUserProfile(current => ({
      paymentTotals: {
        outgoing: { ...mutation.spendingTotals },
        incoming: { ...mutation.incomeTotals },
        all: this.mergePaymentTotals(mutation.spendingTotals, mutation.incomeTotals)
      },
      activities: {
        ...current.activities,
        paymentRefundsPending: pendingRefundCount
      }
    }));
    this.revisionRef.update(value => value + 1);
  }

  private mergePaymentTotals(
    spending: Record<string, number>,
    income: Record<string, number>
  ): Record<string, number> {
    const currencies = new Set([...Object.keys(spending), ...Object.keys(income)]);
    return Object.fromEntries([...currencies].map(currency => [
      currency,
      Math.round(((Number(spending[currency]) || 0) + (Number(income[currency]) || 0)) * 100) / 100
    ]));
  }

  private async openPaymentServiceChat(item: PaymentHistoryItemDto): Promise<void> {
    const activeUserId = this.activeUserId();
    const targetUserId = `${item.recipientUserId ?? ''}`.trim();
    const serviceContext = item.serviceContext === 'asset' ? 'asset' as const : 'event' as const;
    let eventId = `${item.contextEventId ?? (serviceContext === 'event' ? item.sourceId : '')}`.trim();
    let subEventId = `${item.contextSubEventId ?? ''}`.trim();
    const assetId = `${item.contextAssetId ?? (serviceContext === 'asset' ? item.sourceId : '')}`.trim();
    let title = item.sourceId;
    let assetCard: AppDTOs.AssetDTO | AppDTOs.AssetDetailDTO | null = null;
    if (serviceContext === 'asset') {
      assetCard = await this.findPaymentAsset(activeUserId, assetId);
      title = assetCard?.title ?? item.sourceId;
      if (!eventId || !subEventId) {
        const request = (assetCard?.requests ?? []).find(candidate =>
          `${candidate.userId ?? ''}`.trim() === activeUserId
          && (!item.checkoutSessionId || candidate.booking?.paymentSessionId === item.checkoutSessionId)
        );
        eventId = `${request?.booking?.eventId ?? eventId}`.trim();
        subEventId = `${request?.booking?.subEventId ?? subEventId}`.trim();
      }
    } else {
      title = item.sourceId;
    }
    if (!activeUserId || !targetUserId || targetUserId === activeUserId || !eventId
      || (serviceContext === 'asset' && (!assetId || !subEventId))) {
      this.errorRef.set('payment.history.ask.owner.error');
      return;
    }
    if (serviceContext === 'event') {
      await this.users.warmCachedUsers([targetUserId]);
    }
    const activeUser = this.userProfileStore.activeUserProfile()
      ?? this.users.peekCachedUserById(activeUserId);
    const targetUser = serviceContext === 'asset' ? null : this.users.peekCachedUserById(targetUserId);
    const chat: AppDTOs.ChatDTO = {
      id: serviceContext === 'asset'
        ? `c-service-asset-${assetId}-${subEventId}-${activeUserId}`
        : `c-service-event-${eventId}-${activeUserId}`,
      avatar: targetUserId.slice(0, 2).toUpperCase(),
      title: serviceContext === 'asset' ? `Ask Asset Owner · ${title}` : `Contact Organizer · ${title}`,
      lastMessage: serviceContext === 'asset'
        ? `Service chat with the asset owner for ${title}.`
        : `Service chat with the organizer for ${title}.`,
      lastSenderId: targetUserId,
      memberIds: [activeUserId, targetUserId],
      members: ChatPopupHeaderContextConverter.memberSummaries([
        { id: activeUserId, user: activeUser },
        {
          id: targetUserId,
          user: targetUser,
          fallbackName: serviceContext === 'asset' ? assetCard?.ownerName || 'Asset owner' : 'Organizer',
          imageUrl: serviceContext === 'asset' ? assetCard?.ownerAvatarUrl : null
        }
      ]),
      unread: 0,
      dateIso: new Date().toISOString(),
      channelType: 'serviceEvent',
      serviceContext,
      assetId: serviceContext === 'asset' ? assetId : undefined,
      ownerId: serviceContext === 'asset' ? assetId : eventId,
      ownerUserId: activeUserId,
      eventId,
      subEventId: subEventId || undefined
    };
    await this.activities.ensureEventChatPopupLoaded();
    this.activities.openStackedEventChat(
      { ...eventChatPopupRequestFromChat(chat), parentZIndex: 22200 },
      eventChatHeaderStateFromChat(chat)
    );
  }

  private formatSignedCurrency(amount: number, currency: string, sign: '+' | '−'): string {
    const normalizedCurrency = `${currency ?? ''}`.trim().toUpperCase() || 'HUF';
    const currencyFormatter = new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: normalizedCurrency
    });
    const digits = currencyFormatter.resolvedOptions().maximumFractionDigits;
    const value = new Intl.NumberFormat(undefined, {
      minimumFractionDigits: digits,
      maximumFractionDigits: digits
    }).format(Math.abs(Number(amount) || 0));
    return `${normalizedCurrency} ${sign}${value}`;
  }

  private async openPaymentSummary(item: PaymentHistoryItemDto): Promise<void> {
    this.errorRef.set('');
    const userId = this.activeUserId();
    let paymentMethod: SavedPaymentMethodDto | null = null;
    try {
      paymentMethod = await this.paymentMethodForHistoryItem(userId, item);
    } catch {
      // A payment audit outlives the currently saved card. Cash payments never
      // have one, and a tokenized method may have been cleaned up since the
      // transaction, so the read-only summary must remain available without it.
    }
    if (item.fulfillmentKind === 'client') {
      await this.openAssetPaymentSummary(item, paymentMethod);
      return;
    }
    try {
      await this.activities.ensureActivitiesPopupLoaded();
      const detail = await this.events.loadEventDetailById(userId, item.sourceId);
      const record = detail
        ? detail as unknown as AppDTOs.ActivityEventRecord
        : await this.events.queryKnownRecordById(userId, item.sourceId);
      if (!record) {
        this.errorRef.set('payment.summary.error.source.unavailable');
        return;
      }
      this.eventCheckoutDialog.open({
        mode: 'join',
        userId,
        record,
        readOnlySummary: true,
        preloadedCheckoutBasket: await this.paymentSummaryBasket(userId, item, record.title),
        paymentMethod,
        paymentProvider: item.provider,
        paymentStatusLabel: this.paymentStatusLabel(item.status),
        paymentStatusTone: this.paymentStatusTone(item.status),
        paymentNote: this.paymentHistoryNote(item),
        title: 'event.checkout.payment.summary',
        subtitle: record.timeframe,
        failureMessage: this.i18n.translate('payment.summary.error.open'),
        onSubmit: () => undefined
      });
    } catch {
      this.errorRef.set('payment.summary.error.open');
    }
  }

  private async openAssetPaymentSummary(
    item: PaymentHistoryItemDto,
    paymentMethod: SavedPaymentMethodDto | null
  ): Promise<void> {
    this.errorRef.set('');
    const userId = this.activeUserId();
    try {
      const card = await this.findPaymentAsset(userId, item.sourceId);
      if (!card) {
        this.errorRef.set('payment.summary.error.asset.unavailable');
        return;
      }
      const request = (card.requests ?? []).find(candidate =>
        `${candidate.userId ?? ''}`.trim() === userId
        && (!item.checkoutSessionId
          || `${candidate.booking?.paymentSessionId ?? ''}`.trim() === item.checkoutSessionId)
      ) ?? (card.requests ?? []).find(candidate => `${candidate.userId ?? ''}`.trim() === userId) ?? null;
      const audit = item.checkoutSessionId
        ? await this.events.loadCheckoutPaymentAudit(userId, card.id, item.checkoutSessionId)
        : null;
      const startAtIso = `${audit?.bookingStartAtIso ?? request?.booking?.startAtIso ?? item.createdAtIso}`.trim();
      const endAtIso = `${audit?.bookingEndAtIso ?? request?.booking?.endAtIso ?? startAtIso}`.trim();
      const quantity = Math.max(1, Math.trunc(Number(audit?.bookingQuantity ?? request?.booking?.quantity) || 1));
      const currency = `${audit?.currency ?? item.currency ?? 'USD'}`.trim() || 'USD';
      const rows = audit?.pricingSummaryRows?.length
        ? audit.pricingSummaryRows.map(row => ({ ...row }))
        : audit?.lineItems?.length
          ? audit.lineItems.map((line, index) => ({
              key: `payment-history-${line.id || index}`,
              label: line.label,
              detail: line.detail,
              amount: line.amount,
              currency: line.currency,
              multiplier: null
            }))
          : [{
              key: `payment-history-${item.id}`,
              label: card.title,
              detail: request?.booking?.timeframe ?? null,
              amount: item.amount,
              currency,
              multiplier: null
            }];
      await this.assetPopup.ensureAssetPopupLoaded();
      this.assetStore.openAssetEditorEdit({
        cardId: card.id,
        form: AssetCardBuilder.buildAssetFormFromCard(card),
        visibility: AssetCardBuilder.visibilityFromCard(card),
        loading: false,
        readOnly: true,
        runtimeAssignment: {
          quantity,
          quantityMax: quantity,
          quantityLabel: this.i18n.translate('quantity'),
          quantityDescription: request?.booking?.timeframe ?? undefined,
          editable: false
        },
        checkout: {
          sourceId: card.id,
          mode: 'payment-summary',
          phase: 'payment',
          cancellationPolicy: audit?.cancellationPolicy ?? null,
          refundPreview: audit?.refundPreview ?? item.refundPreview ?? null,
          refundPolicyUnavailable: !audit,
          title: this.i18n.translate('event.checkout.payment.summary'),
          subtitle: card.title,
          dateRange: { startAt: startAtIso, endAt: endAtIso, precision: 'minute' },
          dateRangeModel: {
            mode: 'range',
            precision: 'minute',
            valueFormat: 'iso-date-time',
            range: {
              start: { label: this.i18n.translate('asset.borrow.start') },
              end: { label: this.i18n.translate('asset.borrow.end') }
            }
          },
          availableQuantity: quantity,
          pricingPreview: {
            rows,
            totalAmount: Number(audit?.amount ?? item.amount) || 0,
            currency
          },
          acceptedPolicyIds: [...(request?.booking?.acceptedPolicyIds ?? [])],
          footerItems: [],
          busy: false,
          error: null,
          paymentProvider: item.provider,
          paymentProviderLabel: 'event.editor.payment.recorded',
          paymentStatusLabel: audit?.auditKind === 'booking_price_revision'
            ? 'event.editor.payment.recorded.revised'
            : this.paymentStatusLabel(audit?.status ?? item.status),
          paymentStatusTone: this.paymentStatusTone(audit?.status ?? item.status),
          paymentNote: this.paymentHistoryNote(item),
          paymentMethod
        }
      });
    } catch {
      this.errorRef.set('payment.summary.error.open');
    }
  }

  private async paymentMethodForHistoryItem(
    userId: string,
    item: PaymentHistoryItemDto
  ): Promise<SavedPaymentMethodDto> {
    if (item.paymentMethod) {
      return { ...item.paymentMethod };
    }
    const paymentMethodId = `${item.paymentMethodId ?? ''}`.trim();
    if (!paymentMethodId) {
      throw new Error('payment.summary.error.method.unavailable');
    }
    const cached = this.loadedCardsById.get(paymentMethodId);
    if (cached) {
      return { ...cached };
    }
    const page = await this.paymentMethods.queryPage(userId, {
      page: 0,
      pageSize: 6,
      sort: 'createdAt',
      direction: 'desc'
    });
    page.items.forEach(method => this.loadedCardsById.set(method.id, { ...method }));
    const method = this.loadedCardsById.get(paymentMethodId);
    if (!method) {
      throw new Error('payment.summary.error.method.unavailable');
    }
    return { ...method };
  }

  private paymentHistoryNote(item: PaymentHistoryItemDto): string {
    const failureReason = `${item.failureReason ?? ''}`.trim();
    if (item.status.trim().toLowerCase() === 'failed' && failureReason) return failureReason;
    if (!this.isRefundedPaymentStatus(item.status) || !item.refundPreview) return '';
    const preview = item.refundPreview;
    return [
      this.i18n.translateParams('payment.history.refund.preview.amount', {
        amount: this.formatSignedCurrency(
          preview.refundableAmount,
          preview.currency || item.currency || 'HUF',
          '+'
        )
      }),
      this.refundPolicyBasis(item)
    ].filter(Boolean).join('\n');
  }

  private async findPaymentAsset(
    userId: string,
    sourceId: string
  ): Promise<AppDTOs.AssetDTO | AppDTOs.AssetDetailDTO | null> {
    const normalizedSourceId = sourceId.trim();
    if (!normalizedSourceId) return null;
    const cached = this.assets.peekOwnedAssetById(userId, normalizedSourceId);
    if (cached) return cached;
    const detail = await this.assets.loadOwnedAssetDetailById(userId, normalizedSourceId);
    if (detail) return detail;
    const visibleByType = await Promise.all(AppConstants.ASSET_TYPES.map(type =>
      this.assets.queryVisibleAssets({ userId, type })
    ));
    const visible = visibleByType.flat().find(card => card.id === normalizedSourceId) ?? null;
    if (!visible) return null;
    return await this.assets.loadOwnedAssetDetailById(userId, visible.id) ?? visible;
  }

  private async paymentSummaryBasket(
    userId: string,
    item: PaymentHistoryItemDto,
    fallbackLabel: string
  ): Promise<AppDTOs.EventCheckoutBasket> {
    const audit = item.checkoutSessionId
      ? await this.events.loadCheckoutPaymentAudit(userId, item.sourceId, item.checkoutSessionId)
      : null;
    const currency = `${audit?.currency ?? item.currency ?? 'USD'}`.trim() || 'USD';
    const amount = Number(audit?.amount ?? item.amount) || 0;
    const items = audit?.basketItems?.length
      ? audit.basketItems.map(basketItem => ({ ...basketItem }))
      : [{
          id: `payment-history-${item.id}`,
          kind: 'event' as const,
          sourceId: item.sourceId,
          label: fallbackLabel,
          detail: '',
          amount,
          currency,
          quantity: 1,
          status: 'confirmed' as const,
          resultState: item.status === 'failed' ? 'failed' as const : 'succeeded' as const,
          pricingSummaryRows: audit?.pricingSummaryRows?.map(row => ({ ...row })) ?? [],
          checkoutSessionId: item.checkoutSessionId ?? null,
          createdAtIso: item.createdAtIso
        }];
    return {
      userId,
      sourceId: item.sourceId,
      status: 'confirmed',
      items,
      pricingSummaryRows: audit?.pricingSummaryRows?.map(row => ({ ...row })) ?? [],
      lineItems: audit?.lineItems?.map(line => ({ ...line })) ?? [],
      totalAmount: amount,
      currency,
      checkoutSessionId: item.checkoutSessionId ?? null,
      appliedPromoCodes: []
    };
  }

  ngOnDestroy(): void {
    this.stopRegistrationPolling();
  }
}
